use serde_json::json;use sha2::{Digest,Sha256};use std::{fs,path::Path,process::Command};
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/lehmer-inverse175");let d=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-lehmer-inverse175");let mut rows=vec![];for f in["analysis.json","run-plan.json"]{let original=fs::read(r.join(f)).unwrap();let p=d.join(format!("artifacts/{f}.gz"));let decoded=Command::new("gzip").args(["-d","-c"]).arg(&p).output().unwrap();assert!(decoded.status.success());assert_eq!(decoded.stdout,original);rows.push(json!({"file":format!("artifacts/{f}.gz"),"decompressed_sha256":format!("{:x}",Sha256::digest(&original)),"compressed_sha256":format!("{:x}",Sha256::digest(fs::read(p).unwrap())),"decoded_bytes_exact_to_original_reviewed_artifact":true}));}fs::write(d.join("artifacts/storage-review.json"),serde_json::to_vec_pretty(&json!({"passed":true,"storage_only_change":true,"arithmetic_samples_protocol_and_decisions_unchanged":true,"members":rows,"performance_or_native_test_reruns":0})).unwrap()).unwrap();println!("Analysis and full workflow gzip storage matches original reviewed bytes exactly");}
